  http.patch(p, async ({ request }) => {
    const { isNo, delta } = await request.json();
    if (isNo == null || isNaN(Number(isNo))) {
      return HttpResponse.json({ message: "isNo invalid" }, { status: 400 });
    }
    const rows = table("itemstock") || [];
    const id = Number(isNo);
    let idx = rows.findIndex(r => r.itemNo === id);

    // 없으면 스텁 생성
    if (idx < 0) {
      rows.push({
        itemNo: id,
        itemName: `ITEM-${id}`,
        isQty: 0,
        itemPrice: 0,
        totalValue: 0,
        lastUpdate: new Date().toISOString().slice(0, 10),
      });
      idx = rows.length - 1;
    }

    const cur = rows[idx];
    const nextQty = Math.max(0, Number(cur.isQty || 0) + Number(delta || 0));
    const itemPrice = Number(cur.itemPrice || 0);

      rows[idx] = {
        ...cur,
        isQty: nextQty,
        totalValue: nextQty * itemPrice,
        lastUpdate: new Date().toISOString().slice(0, 10),
      };

      setTable("itemstock", rows);
      return HttpResponse.json(clone(rows[idx]));
    })
